#include <Arduino.h>
#include "pins.h"

const uint8_t duties[] = {0, 102, 179, 255};
uint8_t speedStep = 0;
bool rawButton = HIGH, stableButton = HIGH, longHandled = false;
unsigned long startedAt, changedAt = 0, pressedAt = 0;

void setSpeed(uint8_t step) {
  speedStep = step;
  analogWrite(PIN_MOTOR_IN1, duties[step]);
  if (step == 0) digitalWrite(PIN_MOTOR_IN1, LOW);
  Serial.print("Motor percent: ");
  Serial.println(step == 0 ? 0 : step == 1 ? 40 : step == 2 ? 70 : 100);
}

void setup() {
  digitalWrite(PIN_MOTOR_IN1, LOW);
  digitalWrite(PIN_MOTOR_IN2, LOW);
  pinMode(PIN_MOTOR_IN1, OUTPUT);
  pinMode(PIN_MOTOR_IN2, OUTPUT);
  startedAt = millis();
  pinMode(PIN_BUTTON_SIGNAL, INPUT_PULLUP);
  Serial.begin(115200);
  Serial.println("Motor OFF; using core-default PWM frequency.");
}

void loop() {
  unsigned long now = millis();
  if (now - startedAt < 2) return;

  bool reading = digitalRead(PIN_BUTTON_SIGNAL);
  if (reading != rawButton) {
    rawButton = reading;
    changedAt = now;
  }
  if (rawButton != stableButton && now - changedAt >= 30) {
    stableButton = rawButton;
    if (stableButton == LOW) {
      pressedAt = changedAt;
      longHandled = false;
    } else if (!longHandled) {
      if (changedAt - pressedAt >= 800) setSpeed(0);
      else setSpeed((speedStep + 1) % 4);
    }
  }
  if (stableButton == LOW && rawButton == LOW && !longHandled &&
      now - pressedAt >= 800) {
    setSpeed(0);
    longHandled = true;
  }
}
